import { useCallback, useEffect, useMemo, useReducer, useRef } from 'react';
import { useRecoilValue } from 'recoil';
import SweetAlert from '../../../../../components/Shared/Notification';
import { userInformationAtom } from '../../../../../Services/_states';
import {
  normalizeLeadChatUserDetail,
  normalizeMessagesResponse,
} from '../adapters/leadChatAdapter';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import { LEAD_CHAT_MESSAGE_PAGE_SIZE } from '../constants/leadChatApi';
import { leadChatService } from '../services/leadChatService';
import { resolveLeadChatBot } from '../utils/leadChatBotResolver';
import { buildLeadChatContext, getLeadChatKey } from '../utils/leadChatContext';
import { getLeadChatComposerMode, isComposerExpired } from '../utils/leadChatComposerMode';
import {
  isLeadChatApiSuccess,
  parseLeadChatApiError,
} from '../utils/parseLeadChatApiError';
import { buildSessionTogglePayload } from '../utils/leadChatSessionRules';
import {
  applyIncomingMessage,
  applyMessageStatus,
} from '../sockets/handlers/handleIncomingMessage';
import {
  buildOptimisticMessage,
  buildSendMessageFormData,
} from '../utils/leadChatAttachmentUtils';
import {
  LEAD_CHAT_INITIAL_STATE,
  leadChatSessionReducer,
} from './leadChatSessionState';

export default function useLeadChatSession({
  open,
  baseContext,
  formPayload,
  onClose,
}) {
  const userInfo = useRecoilValue(userInformationAtom);
  const currentUserId = userInfo?.id ?? null;
  const agentName = userInfo?.username || userInfo?.first_name || 'Agent';

  const [state, dispatch] = useReducer(leadChatSessionReducer, LEAD_CHAT_INITIAL_STATE);
  const chatKeyRef = useRef('');
  const shouldStickToBottomRef = useRef(true);
  const loadedPagesRef = useRef(new Set([1]));
  const messagesRef = useRef([]);
  const userDetailRequestRef = useRef(0);

  useEffect(() => {
    messagesRef.current = state.messages;
  }, [state.messages]);

  const chatContext = useMemo(() => {
    if (!baseContext?.phoneNumber || !state.conversation.botNumber) return null;
    return buildLeadChatContext(baseContext, state.conversation.botNumber);
  }, [baseContext, state.conversation.botNumber]);

  const resetSession = useCallback(() => {
    dispatch({ type: 'RESET' });
    chatKeyRef.current = '';
    loadedPagesRef.current = new Set([1]);
    shouldStickToBottomRef.current = true;
  }, []);

  useEffect(() => {
    if (!open) {
      resetSession();
    }
  }, [open, resetSession]);

  const resolveBot = useCallback(async () => {
    if (!baseContext?.phoneNumber || !baseContext?.organisationId) return;

    dispatch({ type: 'SET_RESOLVING_BOT', payload: true });
    dispatch({
      type: 'SET_CONVERSATION',
      payload: {
        phoneNumber: baseContext.phoneNumber,
        organisationId: baseContext.organisationId,
        whatsappName: baseContext.whatsappName,
        profileName: baseContext.profileName,
        leadId: baseContext.leadId,
      },
    });

    try {
      const result = await resolveLeadChatBot({
        formPayload,
        organisationId: baseContext.organisationId,
        phoneNumber: baseContext.phoneNumber,
      });

      if (result.error === 'noBots' || !result.botNumber) {
        dispatch({
          type: 'SET_BOT_RESOLUTION',
          payload: { ...result, error: LEAD_CHAT_COPY.errors.noBots },
        });
        SweetAlert(LEAD_CHAT_COPY.errors.noBots, 'error');
        return;
      }

      dispatch({ type: 'SET_BOT_RESOLUTION', payload: result });
    } catch {
      dispatch({
        type: 'SET_BOT_RESOLUTION',
        payload: {
          botNumber: '',
          botOptions: [],
          showSelector: false,
          source: 'error',
          error: LEAD_CHAT_COPY.errors.noBots,
        },
      });
    }
  }, [baseContext, formPayload]);

  useEffect(() => {
    if (!open || !baseContext) return;
    resolveBot();
  }, [open, baseContext?.phoneNumber, baseContext?.organisationId, resolveBot]);

  const loadUserDetail = useCallback(async ({
    phoneNumber,
    botNumber,
    organisationId,
    whatsappName,
  }) => {
    if (!phoneNumber || !botNumber) return null;

    const requestId = userDetailRequestRef.current + 1;
    userDetailRequestRef.current = requestId;
    const requestKey = getLeadChatKey(phoneNumber, botNumber);

    try {
      const res = await leadChatService.getChatSessionState({
        phoneNumber,
        botNumber,
        organisationId,
      });

      if (userDetailRequestRef.current !== requestId) return null;
      if (chatKeyRef.current && chatKeyRef.current !== requestKey) return null;

      const userDetail = normalizeLeadChatUserDetail(res, {
        phoneNumber,
        botNumber,
        whatsappName,
      });
      const composerMode = getLeadChatComposerMode(userDetail, currentUserId);
      dispatch({ type: 'SET_USER_DETAIL', payload: { ...userDetail, composerMode } });
      dispatch({ type: 'SET_COMPOSER_MODE', payload: composerMode });
      return userDetail;
    } catch {
      return null;
    }
  }, [currentUserId]);

  const loadMessages = useCallback(
    async (page = 1, { prepend = false, existingMessages = [] } = {}) => {
      if (!chatContext?.phoneNumber || !chatContext?.botNumber) return;

      const requestKey = getLeadChatKey(chatContext.phoneNumber, chatContext.botNumber);
      chatKeyRef.current = requestKey;

      if (page === 1) {
        dispatch({ type: 'SET_LOADING', payload: true });
        loadedPagesRef.current = new Set([1]);
      } else {
        dispatch({ type: 'SET_LOADING_OLDER', payload: true });
      }

      try {
        const res = await leadChatService.getMessages({
          phone_number: chatContext.phoneNumber,
          botNumber: chatContext.botNumber,
          organisationId: chatContext.organisationId,
          page,
          pageLimit: LEAD_CHAT_MESSAGE_PAGE_SIZE,
        });

        if (chatKeyRef.current !== requestKey) return;

        const { messages, totalCount } = normalizeMessagesResponse(res);
        const chronological = [...messages].reverse();
        const mergedMessages = prepend
          ? [...chronological, ...existingMessages]
          : chronological;

        if (page > 1) {
          loadedPagesRef.current.add(page);
        }

        dispatch({
          type: 'SET_MESSAGES',
          payload: {
            messages: mergedMessages,
            pagination: {
              page,
              totalCount,
              hasMore: messages.length >= LEAD_CHAT_MESSAGE_PAGE_SIZE,
            },
          },
        });
      } catch {
        if (chatKeyRef.current === requestKey) {
          SweetAlert(LEAD_CHAT_COPY.errors.loadFailed, 'error');
        }
      } finally {
        dispatch({ type: 'SET_LOADING', payload: false });
        dispatch({ type: 'SET_LOADING_OLDER', payload: false });
      }
    },
    [chatContext]
  );

  useEffect(() => {
    if (!open || !chatContext?.phoneNumber || !chatContext?.botNumber) return;
    loadUserDetail({
      phoneNumber: chatContext.phoneNumber,
      botNumber: chatContext.botNumber,
      organisationId: chatContext.organisationId,
      whatsappName: baseContext?.whatsappName,
    });
    loadMessages(1);
  }, [
    open,
    baseContext?.whatsappName,
    chatContext?.phoneNumber,
    chatContext?.botNumber,
    chatContext?.organisationId,
    loadMessages,
    loadUserDetail,
  ]);

  const handleBotChange = useCallback(
    (nextBotNumber) => {
      if (!nextBotNumber || nextBotNumber === state.conversation.botNumber) return;
      dispatch({
        type: 'SET_BOT_RESOLUTION',
        payload: {
          botNumber: nextBotNumber,
          botOptions: state.bot.options,
          showSelector: state.bot.showSelector,
          source: 'manual',
        },
      });
      dispatch({
        type: 'SET_MESSAGES',
        payload: { messages: [], pagination: { page: 1, hasMore: false, totalCount: 0 } },
      });
    },
    [state.bot.options, state.bot.showSelector, state.conversation.botNumber]
  );

  const handleSocketPayload = useCallback(
    (parsed) => {
      if (!chatContext?.phoneNumber) return;

      if (parsed.kind === 'message') {
        dispatch({
          type: 'REPLACE_MESSAGES',
          payload: applyIncomingMessage(messagesRef.current, parsed.data, {
            activePhone: chatContext.phoneNumber,
            botNumber: chatContext.botNumber,
          }),
        });
      }

      if (parsed.kind === 'status') {
        dispatch({
          type: 'REPLACE_MESSAGES',
          payload: applyMessageStatus(messagesRef.current, parsed.data),
        });
      }

      if (parsed.kind === 'session' && parsed.data) {
        const patch = parsed.data;
        const userDetail = {
          ...(state.conversation.userDetail || {}),
          ...patch,
          intervene: Boolean(patch.intervene),
          session_start: Boolean(patch.session_start),
          intervened_by: patch.intervened_by ?? state.conversation.userDetail?.intervened_by ?? '',
          intervened_by_user_id:
            patch.intervened_by_user_id ?? state.conversation.userDetail?.intervened_by_user_id ?? null,
        };
        const composerMode = getLeadChatComposerMode(userDetail, currentUserId);
        dispatch({ type: 'SET_USER_DETAIL', payload: { ...userDetail, composerMode } });
        dispatch({ type: 'SET_COMPOSER_MODE', payload: composerMode });
      }
    },
    [chatContext, currentUserId, state.conversation.userDetail]
  );

  const loadOlderMessages = useCallback(() => {
    if (state.ui.isLoadingOlder || !state.pagination.hasMore) return;
    const nextPage = state.pagination.page + 1;
    if (loadedPagesRef.current.has(nextPage)) return;
    loadMessages(nextPage, { prepend: true, existingMessages: state.messages });
  }, [loadMessages, state.messages, state.pagination.hasMore, state.pagination.page, state.ui.isLoadingOlder]);

  const handleSendMessage = useCallback(
    async (file) => {
      if (!chatContext?.phoneNumber || !chatContext?.botNumber) return;
      const draft = state.ui.draft.trim();
      if (!file && !draft) return;

      dispatch({ type: 'SET_SENDING', payload: true });
      shouldStickToBottomRef.current = true;

      const optimistic = buildOptimisticMessage({
        phoneNumber: chatContext.phoneNumber,
        botNumber: chatContext.botNumber,
        draftMessage: draft,
        file,
      });

      dispatch({ type: 'APPEND_MESSAGE', payload: optimistic });
      dispatch({ type: 'SET_DRAFT', payload: '' });

      try {
        const formData = buildSendMessageFormData({
          phoneNumber: chatContext.phoneNumber,
          draftMessage: draft,
          file,
        });
        await leadChatService.sendMessage(formData, chatContext.botNumber);
      } catch {
        SweetAlert(LEAD_CHAT_COPY.errors.sendFailed, 'error');
        dispatch({ type: 'REMOVE_MESSAGE', payload: optimistic.msg_id });
      } finally {
        dispatch({ type: 'SET_SENDING', payload: false });
      }
    },
    [chatContext, state.messages, state.ui.draft]
  );

  const toggleSession = useCallback(async () => {
    if (!chatContext?.phoneNumber || !chatContext?.botNumber) return;
    const user = state.conversation.userDetail || {};
    const start = !(user.intervene && user.session_start);

    if (start && isComposerExpired(state.ui.composerMode)) {
      SweetAlert(LEAD_CHAT_COPY.errors.sessionExpired, 'error');
      return;
    }

    try {
      const payload = buildSessionTogglePayload({
        phoneNumber: chatContext.phoneNumber,
        botNumber: chatContext.botNumber,
        organisationId: chatContext.organisationId,
        whatsappName: baseContext?.profileName || user.whatsapp_name,
        user,
        start,
        leadId: chatContext.leadId,
        recordId: chatContext.rowId,
        leadsFormId: chatContext.leadsFormId,
      });
      userDetailRequestRef.current += 1;
      const res = await leadChatService.toggleSession(payload);

      if (!isLeadChatApiSuccess(res)) {
        throw new Error(parseLeadChatApiError(res, LEAD_CHAT_COPY.errors.sessionFailed));
      }

      const nextUser = start
        ? {
            ...user,
            intervene: true,
            session_start: true,
            intervened_by: agentName,
            intervened_by_user_id: currentUserId,
            last_active_date: user.last_active_date || new Date().toISOString(),
          }
        : {
            ...user,
            intervene: false,
            session_start: false,
            intervened_by: '',
            intervened_by_user_id: null,
            last_active_date: user.last_active_date || null,
          };
      const composerMode = getLeadChatComposerMode(nextUser, currentUserId);
      dispatch({ type: 'SET_USER_DETAIL', payload: { ...nextUser, composerMode } });
      dispatch({ type: 'SET_COMPOSER_MODE', payload: composerMode });
      SweetAlert(
        start ? LEAD_CHAT_COPY.header.sessionStarted : LEAD_CHAT_COPY.header.sessionEnded,
        'success'
      );
    } catch (err) {
      const message = err?.response
        ? parseLeadChatApiError(err.response, LEAD_CHAT_COPY.errors.sessionFailed)
        : (err?.message || LEAD_CHAT_COPY.errors.sessionFailed);
      SweetAlert(message, 'error');
    }
  }, [
    agentName,
    baseContext?.whatsappName,
    chatContext,
    currentUserId,
    state.conversation.userDetail,
    state.ui.composerMode,
  ]);

  return {
    state,
    chatContext,
    agentName,
    currentUserId,
    dispatch,
    onClose,
    handleBotChange,
    handleSocketPayload,
    loadOlderMessages,
    handleSendMessage,
    toggleSession,
    shouldStickToBottomRef,
  };
}
