import React, { useMemo } from 'react';
import { Box, CircularProgress, Typography } from '@mui/material';
import InfiniteSearchableSelect from '../../../../../components/ui/SearchableSelect/InfiniteSearchableSelect';
import SearchableSelect from '../../../../../components/ui/SearchableSelect/SearchableSelect';
import { getFormControlSx } from '../../../../../components/ui/Form/controls/formControlStyles';
import { useFeatureTheme } from '../../../../../theme/hooks/useFeatureTheme';
import { fetchBotNumberListPage } from '../../../../whatsapp-templates/adapters/botNumberListAdapter';
import { mapBotToSelectOption } from '../../../../whatsapp-templates/utils/normalizeTemplate';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import useLeadChatSx from '../hooks/useLeadChatSx';

const isSameBot = (a, b) =>
  (a?.wa_phone_number ?? a?.value) === (b?.wa_phone_number ?? b?.value);
const getBotId = (option) => option?.wa_phone_number ?? option?.value ?? option?.id ?? null;
const getBotLabel = (option) => option?.label ?? option?.wa_phone_number ?? '';

export default function LeadChatBotSelect({
  organisationId,
  botNumber,
  botValue,
  showSelector,
  isResolving,
  onBotChange,
}) {
  const sx = useLeadChatSx();
  const themeTokens = useFeatureTheme();
  const selectSx = useMemo(() => getFormControlSx(themeTokens), [themeTokens]);

  if (isResolving) {
    return (
      <Box sx={sx.botSelect}>
        <CircularProgress size={16} sx={{ mr: 1 }} />
        <Typography variant="caption" color="text.secondary">
          {LEAD_CHAT_COPY.botSelect.resolving}
        </Typography>
      </Box>
    );
  }

  if (!showSelector) return null;

  return (
    <Box sx={sx.botSelect}>
      <InfiniteSearchableSelect
        label={LEAD_CHAT_COPY.botSelect.label}
        placeholder={LEAD_CHAT_COPY.botSelect.placeholder}
        extraParams={{ organisation_id: organisationId }}
        fetchPage={fetchBotNumberListPage}
        pageSize={20}
        enabled={Boolean(organisationId)}
        loadOnOpen
        valueId={botNumber || null}
        selectedSeed={botValue}
        mapToOption={mapBotToSelectOption}
        isSameOption={isSameBot}
        getOptionId={getBotId}
        getOptionLabel={getBotLabel}
        isOptionEqualToValue={isSameBot}
        onChange={(option) => onBotChange?.(option?.wa_phone_number ?? option?.value ?? '')}
        SelectComponent={SearchableSelect}
        noOptionsText="No bot numbers found"
        disabled={!organisationId}
        sx={selectSx}
        shrinkLabel
      />
    </Box>
  );
}
