import * as XLSX from 'xlsx';
import { getBulkSheetParamColumns } from '../../../whatsapp-templates/utils/bulkSheetValidation';

function buildErrorSummary(errors = []) {
  return errors.map((error) => error.message).join('; ');
}

function buildErrorFields(errors = []) {
  return errors.map((error) => error.field).join(',');
}

export function buildLeadTemplateErrorSheetWorkbook({
  template,
  rowResults = [],
  includeAllRows = true,
  guideLines = [],
}) {
  const paramColumns = getBulkSheetParamColumns(template);
  const dataColumns = ['phone_number', ...paramColumns.filter((col) => col !== 'phone_number')];

  const sourceRows = includeAllRows
    ? rowResults
    : rowResults.filter((entry) => entry.errors?.length);

  const sheetRows = sourceRows.map((entry) => {
    const output = {
      row_number: entry.rowNumber,
    };

    dataColumns.forEach((col) => {
      output[col] = entry.row?.[col] ?? '';
    });

    output.error_summary = buildErrorSummary(entry.errors ?? []);
    output.error_fields = buildErrorFields(entry.errors ?? []);
    return output;
  });

  const headers = ['row_number', ...dataColumns, 'error_summary', 'error_fields'];
  const dataSheet = XLSX.utils.json_to_sheet(sheetRows, { header: headers });
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, dataSheet, 'data_with_errors');

  if (guideLines.length) {
    const guideRows = guideLines.map((line) => ({ instruction: line }));
    const guideSheet = XLSX.utils.json_to_sheet(guideRows, { header: ['instruction'] });
    XLSX.utils.book_append_sheet(workbook, guideSheet, 'error_guide');
  }

  return workbook;
}

export function downloadLeadTemplateErrorSheet({
  template,
  rowResults = [],
  guideLines = [],
}) {
  const workbook = buildLeadTemplateErrorSheetWorkbook({
    template,
    rowResults,
    includeAllRows: true,
    guideLines,
  });
  const safeName = String(template?.name ?? 'template').replace(/[^\w.-]+/g, '_');
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  XLSX.writeFile(workbook, `template-send-errors-${safeName}-${stamp}.xlsx`);
}
