import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { buildFormStudioRoute } from '../../utils/businessFunctionRoutes';
import { openRecordWebForm } from '../utils/recordWebFormUtils';

export default function useRecordNavigation({
  accountId,
  workspaceId,
  tableId,
  formPayload,
  table,
}) {
  const navigate = useNavigate();

  const navigateToEnterRecords = useCallback(() => {
    if (!workspaceId) return;
    navigate(`/r/records/${encodeURIComponent(workspaceId)}/enterLeads`);
  }, [navigate, workspaceId]);

  const navigateToImportRecords = useCallback(() => {
    if (!workspaceId || !tableId) return;
    navigate(`/r/records/${encodeURIComponent(workspaceId)}/importLeads/${encodeURIComponent(tableId)}`);
  }, [navigate, tableId, workspaceId]);

  const navigateToEditForm = useCallback(() => {
    if (!accountId || !workspaceId || !tableId) return;
    navigate(buildFormStudioRoute(accountId, workspaceId, tableId), {
      state: {
        leadFormData: {
          leads_form_id: tableId,
          leads_form_name: table?.name,
          leads_form_items: table?.leadsFormItems,
          ...(formPayload ?? {}),
        },
      },
    });
  }, [accountId, formPayload, navigate, table, tableId, workspaceId]);

  const openWebForm = useCallback(
    (row) => openRecordWebForm({
      row,
      workspaceId,
      table,
      formPayload,
    }),
    [formPayload, table, workspaceId]
  );

  return {
    navigateToEnterRecords,
    navigateToImportRecords,
    navigateToEditForm,
    openWebForm,
  };
}
