// src/features/business-functions/records/utils/recordColumnVisibilityStorage.js

export function getColumnVisibilityStorageKey(tableId, profileId) {
  if (!tableId) return null;
  const userSegment = profileId != null ? String(profileId) : 'default';
  return `bf_col_vis_${tableId}_${userSegment}`;
}

export function loadSavedColumnVisibility(tableId, profileId) {
  try {
    const key = getColumnVisibilityStorageKey(tableId, profileId);
    if (!key || typeof window === 'undefined' || !window.localStorage) return null;
    const raw = window.localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed;
    }
    return null;
  } catch (err) {
    console.warn('Failed to load column visibility from storage:', err);
    return null;
  }
}

export function saveColumnVisibilityToStorage(tableId, profileId, visibility) {
  try {
    const key = getColumnVisibilityStorageKey(tableId, profileId);
    if (!key || typeof window === 'undefined' || !window.localStorage) return;
    if (!visibility || typeof visibility !== 'object') return;
    window.localStorage.setItem(key, JSON.stringify(visibility));
  } catch (err) {
    console.warn('Failed to save column visibility to storage:', err);
  }
}

export function clearSavedColumnVisibility(tableId, profileId) {
  try {
    const key = getColumnVisibilityStorageKey(tableId, profileId);
    if (!key || typeof window === 'undefined' || !window.localStorage) return;
    window.localStorage.removeItem(key);
  } catch (err) {
    console.warn('Failed to clear column visibility from storage:', err);
  }
}
