import React from 'react';
import AddIcon from '@mui/icons-material/Add';
import FilterListIcon from '@mui/icons-material/FilterList';
import RefreshIcon from '@mui/icons-material/Refresh';
import ViewColumnIcon from '@mui/icons-material/ViewColumn';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { Box, Badge, Chip } from '@mui/material';
import { Button, TableToolbar } from '../../../../components/ui';
import { RECORD_COPY } from '../constants/recordCopy';
import RecordToolbarIconActions from './RecordToolbarIconActions';
import RecordToolbarIconButton from './RecordToolbarIconButton';

export default function RecordsToolbar({
  styles,
  search,
  onRefresh,
  onAddRecord,
  onOpenHelp,
  showHelpIcon = false,
  onOpenFilters,
  onOpenColumns,
  permissions = {},
  onDownload,
  onEnterRecords,
  onImportRecords,
  onEditForm,
  filterCount = 0,
  canCreate = false,
  canFilter = true,
  totalCount = 0,
  uniquePhoneCount = 0,
}) {
  return (
    <Box sx={styles?.recordsToolbarRoot}>
      <TableToolbar
        search={search}
        searchSummary={{ totalCount, uniquePhoneCount }}
        actions={
          <Box sx={styles?.recordsToolbarActions}>
            {canFilter ? (
              <Badge badgeContent={filterCount || null} color="primary">
                <Button
                  variant="outline"
                  size="sm"
                  icon={<FilterListIcon />}
                  onClick={(event) => onOpenFilters?.(event)}
                >
                  {RECORD_COPY.filters}
                </Button>
              </Badge>
            ) : null}

            <RecordToolbarIconButton
              title={RECORD_COPY.columns}
              ariaLabel={RECORD_COPY.columns}
              onClick={onOpenColumns}
              icon={<ViewColumnIcon />}
            />

            <RecordToolbarIconButton
              title={RECORD_COPY.refresh}
              ariaLabel={RECORD_COPY.refresh}
              onClick={onRefresh}
              icon={<RefreshIcon />}
            />

            <RecordToolbarIconActions
              permissions={permissions}
              onDownload={onDownload}
              onImportRecords={onImportRecords}
              onEditForm={onEditForm}
              onEnterRecords={onEnterRecords}
            />

            {canCreate ? (
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Button
                  variant="primary"
                  size="sm"
                  icon={<AddIcon />}
                  onClick={onAddRecord}
                >
                  {RECORD_COPY.addRecord}
                </Button>
                {showHelpIcon ? (
                  <RecordToolbarIconButton
                    title={RECORD_COPY.help.title || 'Help files'}
                    ariaLabel={RECORD_COPY.help.title || 'Help files'}
                    onClick={onOpenHelp}
                    icon={<HelpOutlineIcon />}
                  />
                ) : null}
              </Box>
            ) : null}
          </Box>
        }
        sx={styles?.recordsTableToolbar}
      />
    </Box>
  );
}

export function RecordsFilterSummary({ count, onClear, styles }) {
  if (!count) return null;

  return (
    <Box sx={styles?.recordsFilterSummary}>
      <Chip
        label={`${count} filter${count === 1 ? '' : 's'} applied`}
        onDelete={onClear}
        size="small"
        sx={{ borderRadius: 0 }}
      />
    </Box>
  );
}
