const TYPE_ALIASES = {
  TEXT: 'text',
  TEMPLATE: 'template',
  IMAGE: 'image',
  VIDEO: 'video',
  AUDIO: 'audio',
  DOCUMENT: 'document',
  FILE: 'document',
  BUTTONS: 'buttons',
  LIST: 'list',
};

function get(obj, path) {
  if (!obj) return undefined;
  return path.split('.').reduce((acc, key) => (acc == null ? undefined : acc[key]), obj);
}

function firstText(...values) {
  return values.find((value) => typeof value === 'string' && value.trim()) || '';
}

function normalizeRawType(rawType) {
  if (!rawType || typeof rawType !== 'string') return 'text';
  return TYPE_ALIASES[rawType.toUpperCase()] || rawType.toLowerCase();
}

function normalizeStatus(message) {
  const status = message?.status?.type || message?.status || message?.message_status;
  if (!status) return null;
  if (typeof status === 'string') return status.toLowerCase();
  if (typeof status === 'object') return (status.type || status.status || '').toLowerCase();
  return `${status}`.toLowerCase();
}

function detectKind(message, rawType) {
  const type = normalizeRawType(rawType);
  if (type === 'image' || type === 'video' || type === 'audio' || type === 'document' || type === 'template') {
    return type;
  }

  const mediaMime = firstText(
    message?.content?.mime_type,
    message?.mime_type,
    message?.file_type
  );
  if (mediaMime.startsWith('image/')) return 'image';
  if (mediaMime.startsWith('audio/')) return 'audio';
  if (mediaMime.startsWith('video/')) return 'video';
  if (mediaMime.includes('pdf') || mediaMime.includes('document')) return 'document';

  return type || 'text';
}

function extractMediaUrl(message) {
  const content = message?.content || {};
  return firstText(
    get(content, 'media.s3_object.url'),
    get(content, 'media.url'),
    content.previewUrl,
    content.url,
    message?.url,
    get(content, 'header.link'),
    get(content, 'header.url'),
    get(content, 'image.link'),
    get(content, 'image.url'),
    get(content, 'video.link'),
    get(content, 'video.url'),
    get(content, 'document.link'),
    get(content, 'document.url'),
    get(content, 'audio.link'),
    get(content, 'audio.url'),
    get(message, 'document.url'),
    get(message, 'image.url'),
    get(message, 'video.url'),
    get(message, 'audio.url'),
    message?.media_url
  );
}

function extractFileName(message) {
  const content = message?.content || {};
  return firstText(
    content.filename,
    content.file_name,
    content.name,
    get(content, 'document.filename'),
    get(content, 'document.name'),
    get(content, 'media.filename'),
    get(message, 'document.filename'),
    get(message, 'document.name')
  );
}

function extractHeader(message) {
  const header = message?.content?.header || message?.header;
  if (!header || typeof header !== 'object') return null;

  const headerType = `${header.type || header.format || ''}`.toUpperCase();
  const url = firstText(
    header.link,
    header.url,
    header.image?.link,
    header.image?.url,
    header.video?.link,
    header.video?.url,
    header.document?.link,
    header.document?.url
  );
  const fileName = firstText(
    header.filename,
    header.file_name,
    header.name,
    header.document?.filename
  );

  if (headerType === 'IMAGE' || headerType === 'PHOTO') {
    return { kind: 'image', url, fileName };
  }
  if (headerType === 'VIDEO') {
    return { kind: 'video', url, fileName };
  }
  if (headerType === 'DOCUMENT' || headerType === 'FILE' || headerType === 'PDF') {
    return { kind: 'document', url, fileName: fileName || 'Document' };
  }
  if (url) {
    return { kind: 'document', url, fileName: fileName || 'Document' };
  }
  return null;
}

export function normalizeLeadChatMessage(message) {
  if (!message) {
    return {
      kind: 'text',
      text: '',
      timestamp: null,
      status: null,
      isMine: false,
      mediaUrl: '',
      media: null,
      header: null,
      raw: message,
    };
  }

  const rawType =
    message?.content?.type
    || message?.content?.body?.type
    || message?.type
    || 'text';

  const kind = detectKind(message, rawType);
  const text = firstText(
    message?.content?.body?.text,
    message?.content?.text,
    message?.text,
    message?.message
  );
  const mediaUrl = extractMediaUrl(message);
  const fileName = extractFileName(message);
  const mediaKind = kind === 'image' || kind === 'video' || kind === 'audio' || kind === 'document'
    ? kind
    : null;

  const timestamp =
    message?.created_at
    || message?.timestamp
    || message?.updated_at
    || null;

  const origin = `${message?.origin || ''}`.toUpperCase();
  const isMine = origin === 'OUTBOUND';

  return {
    kind,
    text,
    timestamp,
    status: normalizeStatus(message),
    isMine,
    mediaUrl,
    fileName,
    media: mediaKind
      ? {
          kind: mediaKind,
          url: mediaUrl || null,
          fileName: fileName || null,
          caption: text || null,
        }
      : null,
    header: extractHeader(message),
    templateName: message?.template_name || message?.content?.template_name || '',
    raw: message,
  };
}

export function getMessageKey(message, index) {
  const id = message?.msg_id || message?.w_id || message?.id || message?.message_id;
  return id ? String(id) : `idx-${index}`;
}
