import dayjs from 'dayjs';
import { dateFormate, indianTimeZone } from '../../../../utils/helper.jsx';
import { getRecordMongoId } from './recordInlineEditUtils';

export function normalizeStatusValue(value) {
  return String(value ?? '').trim().toLowerCase();
}

export function getFirstValue(obj = {}, keys = []) {
  for (const key of keys) {
    const value = obj?.[key];
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }
  return '';
}

export function formatStatusLogDate(value) {
  if (!value) return '-';
  try {
    return dateFormate(indianTimeZone(value), 'DD-MM-YYYY hh:mm A');
  } catch {
    return String(value);
  }
}

export function formatSummaryDate(value) {
  if (!value) return '-';
  try {
    return dateFormate(indianTimeZone(value), 'DD-MM-YYYY');
  } catch {
    const parsed = dayjs(value);
    return parsed.isValid() ? parsed.format('DD-MM-YYYY') : String(value).split('T')[0];
  }
}

export function toTimestamp(value) {
  if (!value) return null;
  const time = new Date(value).getTime();
  return Number.isNaN(time) ? null : time;
}

export function formatDuration(seconds) {
  if (seconds === undefined || seconds === null || Number.isNaN(seconds)) {
    return '-';
  }

  const total = Math.max(0, Math.round(seconds));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;

  if (hours > 0) {
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }

  return `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
}

function getTemplateNames(value) {
  if (value === null || value === undefined || value === '') return [];

  if (typeof value === 'string') {
    const name = value.trim();
    return name ? [name] : [];
  }

  if (Array.isArray(value)) {
    const result = [];
    value.forEach((item) => {
      if (item === null || item === undefined) return;
      if (typeof item === 'string') {
        const name = item.trim();
        if (name) result.push(name);
        return;
      }
      if (typeof item === 'object') {
        const name = item.template_name ?? item.name ?? item.templateName ?? item.template;
        if (typeof name === 'string' && name.trim()) {
          result.push(name.trim());
        }
      }
    });
    return [...new Set(result)];
  }

  if (typeof value === 'object') {
    const name = value.template_name ?? value.name ?? value.templateName ?? value.template;
    if (typeof name === 'string' && name.trim()) {
      return [name.trim()];
    }
  }

  return [];
}

export function getTemplateNamesFromRow(row = {}) {
  const result = [...getTemplateNames(row.template_name)];

  const template = row.template;
  if (Array.isArray(template)) {
    template.forEach((item) => {
      if (item?.name) result.push(String(item.name).trim());
    });
  } else if (template && typeof template === 'object') {
    const name = template.name || template.template_name;
    if (name) result.push(String(name).trim());
  }

  return [...new Set(result.filter(Boolean))];
}

export function getTemplateIdFromRow(row = {}, templateName) {
  const directId = row.template_id || row.templateId;
  if (directId !== undefined && directId !== null && directId !== '') {
    return String(directId);
  }

  const template = row.template;
  if (Array.isArray(template)) {
    const matched = template.find((item) => {
      const itemName = item?.name || item?.template_name || '';
      if (templateName) {
        return normalizeStatusValue(itemName) === normalizeStatusValue(templateName);
      }
      return Boolean(item?.id || item?.template_id);
    });

    if (matched?.id) return String(matched.id);
    if (matched?.template_id) return String(matched.template_id);

    const firstWithId = template.find((item) => item?.id || item?.template_id);
    if (firstWithId?.id) return String(firstWithId.id);
    if (firstWithId?.template_id) return String(firstWithId.template_id);
  }

  if (template && typeof template === 'object') {
    if (template.id) return String(template.id);
    if (template.template_id) return String(template.template_id);
  }

  const fallbackId = row.md_id || row.template_md_id;
  if (fallbackId) return String(fallbackId);

  return '';
}

export function getStatusLabel(row = {}) {
  return row.status_name || row.name || '-';
}

export function getStatusBadgeVariant(status = '') {
  const value = normalizeStatusValue(status);

  if (value.includes('resolved') || value.includes('connected') || value.includes('delivered')) {
    return 'success';
  }
  if (value.includes('failed') || value.includes('not connected') || value.includes('bounce')) {
    return 'error';
  }
  if (value.includes('read') || value.includes('click') || value.includes('open')) {
    return 'info';
  }
  if (value.includes('later') || value.includes('progress')) {
    return 'warning';
  }
  return 'neutral';
}

export function getTypeLabel(row = {}) {
  const type = normalizeStatusValue(row.type_of_status);

  if (type === 'u' || type === 'user') return 'User';
  if (type === 'a' || type === 'agent') return 'Agent';
  if (type === 's' || type === 'system') return 'System';

  return row.role || row.type || 'System';
}

function isUserEvent(row) {
  const status = normalizeStatusValue(getStatusLabel(row));
  return (
    status.includes('read')
    || status.includes('button clicked')
    || status.includes('cta click')
    || status === 'click'
    || status.includes('chat')
  );
}

function isDeliveredEvent(row) {
  return normalizeStatusValue(getStatusLabel(row)).includes('delivered');
}

function isReadEvent(row) {
  return normalizeStatusValue(getStatusLabel(row)).includes('read');
}

function isCtaEvent(row) {
  const status = normalizeStatusValue(getStatusLabel(row));
  return (
    (status.includes('cta') && (status.includes('click') || status.includes('clicked')))
    || status.includes('button clicked')
  );
}

function isChatEvent(row) {
  return normalizeStatusValue(getStatusLabel(row)).includes('chat');
}

function isAgentResponseEvent(row) {
  const status = normalizeStatusValue(getStatusLabel(row));
  return (
    status.includes('cta open')
    || status.includes('call connected')
    || status.includes('connected')
    || status.includes('call not connected')
    || status.includes('not connected')
    || status.includes('call later')
    || status.includes('call scheduled')
    || status.includes('intervene')
    || status.includes('resolved')
    || status.includes('feedback')
  );
}

function getLatestBefore(rows, currentIndex, predicate) {
  for (let i = currentIndex - 1; i >= 0; i -= 1) {
    if (predicate(rows[i])) {
      return rows[i];
    }
  }
  return undefined;
}

export function getResponseInfo(rows = [], index = 0) {
  const current = rows[index];
  const currentTime = toTimestamp(current?.updated_at || current?.created_at);

  if (currentTime === null) {
    return { from: '-', seconds: null };
  }

  if (isUserEvent(current)) {
    let previousUserEvent;

    if (isReadEvent(current)) {
      previousUserEvent = getLatestBefore(rows, index, isDeliveredEvent);
    } else if (isCtaEvent(current)) {
      previousUserEvent = getLatestBefore(rows, index, isReadEvent)
        || getLatestBefore(rows, index, isDeliveredEvent);
    } else if (isChatEvent(current)) {
      previousUserEvent = getLatestBefore(rows, index, isDeliveredEvent);
    }

    const previousTime = toTimestamp(
      previousUserEvent?.updated_at || previousUserEvent?.created_at
    );

    return {
      from: getStatusLabel(previousUserEvent || {}),
      seconds: previousTime === null
        ? null
        : Math.max(0, (currentTime - previousTime) / 1000),
    };
  }

  if (isAgentResponseEvent(current)) {
    const previousUser = getLatestBefore(rows, index, isUserEvent);
    const previousTime = toTimestamp(previousUser?.updated_at || previousUser?.created_at);

    return {
      from: getStatusLabel(previousUser || {}),
      seconds: previousTime === null
        ? null
        : Math.max(0, (currentTime - previousTime) / 1000),
    };
  }

  return { from: '-', seconds: null };
}

export function getSummaryDate(row = {}) {
  return String(row.sent_date || row.date || row.created_at || row.sentDate || '');
}

export function getSubStatusLabel(row = {}) {
  return row.sub_status || row.substatus || row.sub_status_name || '-';
}

export function getTriggeredBy(row = {}) {
  return row.created_by || row.role || 'System';
}

export function collectPayloadKeys(rows = []) {
  const keys = new Set();
  rows.forEach((row) => {
    Object.keys(row?.payload || {}).forEach((key) => keys.add(key));
  });
  return Array.from(keys);
}

export function getTemplateDetailPayloadKeys(templateData = {}) {
  if (!templateData || typeof templateData !== 'object') return [];

  return Object.keys(templateData).filter(
    (key) => !['md_id', 'template_id', 'id', 'name', 'template_name'].includes(key)
  );
}

export function resolveLeadIdForStatusLogs(selectedRow = {}) {
  return getRecordMongoId(selectedRow);
}

export function resolveBotNumber(selectedRow = {}) {
  return getFirstValue(selectedRow, [
    'bot_number',
    'phone_number',
    'mobile',
    'mobile_number',
  ]);
}

export function normalizeApiList(response) {
  const payload = response?.data ?? response;
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.results)) return payload.results;
  if (Array.isArray(payload?.list)) return payload.list;
  if (Array.isArray(payload?.users)) return payload.users;
  if (Array.isArray(payload?.data?.data)) return payload.data.data;
  if (Array.isArray(payload?.data?.users)) return payload.data.users;
  return [];
}

export function extractTemplateUsersTotal(response, users = []) {
  const payload = response?.data ?? response;
  return Number(
    payload?.total_count
    ?? payload?.total_users
    ?? payload?.data?.total_count
    ?? payload?.data?.total_users
    ?? users.length
  ) || users.length;
}

export function extractResolvedTemplateId(response) {
  const result = response?.data ?? response;
  const templateData = result?.data || result?.template || result;

  const templateId = templateData?.id
    || templateData?.template_id
    || templateData?.md_id
    || templateData?.data?.id
    || templateData?.data?.template_id
    || '';

  if (templateId) return String(templateId);

  if (Array.isArray(result)) {
    const first = result[0];
    const arrayId = first?.id || first?.template_id || first?.md_id || '';
    if (arrayId) return String(arrayId);
  }

  return '';
}
