// src/features/business-functions/adapters/tableRecordsAdapter.js

function inferColumnType(keyType) {
  const value = (keyType || '').toUpperCase();
  if (value.includes('DATE') || value.includes('TIME')) return 'date';
  if (value.includes('NUMBER') || value.includes('INTEGER') || value.includes('FLOAT')) return 'number';
  if (value.includes('BOOLEAN')) return 'badge';
  if (value.includes('PHONE')) return 'phone';
  return 'text';
}

function normalizeColumn(field, index) {
  if (!field) return null;

  const key = field.key ?? field.key_name ?? field.field ?? field.name ?? `col_${index}`;

  return {
    key,
    header: field.header ?? field.label ?? field.display_name ?? field.alias_name ?? field.key_name ?? field.name ?? 'Column',
    type: field.type ?? inferColumnType(field.key_type ?? field.field_type),
    priority: ['lead_id', 'phone_number', 'created_at', 'status'].includes(key),
    fieldMeta: {
      key_name: field.key_name ?? key,
      key_type: field.key_type ?? field.field_type ?? '',
      statusOption: field.statusOption ?? '',
      status_parent_key: field.status_parent_key ?? '',
      access_level: field.access_level ?? '',
      entity: field.entity ?? null,
      query_parameter: field.query_parameter ?? [],
      selectedEntityFields: field.selectedEntityFields ?? [],
      data_type: field.data_type ?? '',
      option_colors: field.option_colors ?? null,
    },
  };
}

/**
 * Unwrap nested API shapes: { "508": { leads_form_items } } or { data: { ... } }.
 */
export function unwrapFormPayload(raw) {
  const payload = raw?.data && typeof raw.data === 'object' ? raw.data : raw;
  if (!payload || typeof payload !== 'object') return null;

  if (payload.leads_form_items) return payload;

  const nestedForms = Object.values(payload).filter(
    (entry) => entry && typeof entry === 'object' && entry.leads_form_items
  );
  if (nestedForms.length === 1) {
    return nestedForms[0];
  }

  return payload;
}

function extractFormItems(raw) {
  const payload = unwrapFormPayload(raw);
  if (!payload || typeof payload !== 'object') return [];

  const items = payload.leads_form_items ?? payload.data ?? payload;
  if (Array.isArray(items)) return items;
  if (typeof items === 'object') return Object.values(items).filter(Boolean);
  return [];
}

/**
 * Build table columns from all lead form field definitions (including static columns).
 */
export function adaptLeadsFormItemsToColumns(rawForm) {
  const items = extractFormItems(rawForm);
  const seenKeys = new Set();

  return items
    .sort((a, b) => {
      const orderA = a.order_id ?? a.item_id ?? 0;
      const orderB = b.order_id ?? b.item_id ?? 0;
      return orderA - orderB;
    })
    .map(normalizeColumn)
    .filter((col) => {
      if (!col?.key || seenKeys.has(col.key)) return false;
      seenKeys.add(col.key);
      return true;
    });
}

function resolveStaticLeadValue(lead, key) {
  if (!lead || !key) return undefined;

  if (key === 'last_machadalo_comment.comment') {
    const comment = lead.last_machadalo_comment;
    if (Array.isArray(comment)) {
      return comment[0]?.comment ?? '';
    }
    if (comment && typeof comment === 'object') {
      return comment.comment ?? '';
    }
    return '';
  }

  if (key === 'audio_summary') {
    const summary = lead.audio_summary;
    if (typeof summary === 'string') return summary;
    if (summary?.transcript) return summary.transcript;
    return summary ? 'Available' : '';
  }

  if (key === 'aichat') {
    const chat = lead.aichat;
    if (Array.isArray(chat)) {
      return chat.length > 0 ? `${chat.length} message(s)` : '';
    }
    return chat ? String(chat) : '';
  }

  return undefined;
}

export function getLeadFieldValue(lead, key) {
  if (!lead || !key) return '';

  const staticValue = resolveStaticLeadValue(lead, key);
  if (staticValue !== undefined) {
    return staticValue;
  }

  const fromData = Array.isArray(lead.data)
    ? lead.data.find((cell) => cell?.key_name === key)
    : null;

  if (fromData?.value != null && fromData?.value !== '') {
    return fromData.value;
  }

  if (lead[key] != null && lead[key] !== '') {
    return lead[key];
  }

  return '';
}

function normalizeRow(row, index, columns) {
  if (!row || typeof row !== 'object') {
    return { id: String(index) };
  }

  if (Array.isArray(row.data)) {
    const record = {
      id: String(row.id ?? row.lead_id ?? row.action?.id ?? index),
      lead_id: row.lead_id ?? row.id,
      _mongoId: row.id,
      _rawLead: row,
    };

    columns.forEach((column) => {
      record[column.key] = getLeadFieldValue(row, column.key);
    });

    return record;
  }

  if (Array.isArray(row.fields)) {
    const record = {
      id: row.action?.id ?? String(index),
      entryId: row.fields.find((cell) => cell.entry_id)?.entry_id ?? index,
    };

    row.fields.forEach((cell, cellIndex) => {
      const key = columns[cellIndex]?.key ?? `col_${cellIndex}`;
      record[key] = cell?.value ?? '';
    });

    if (row.action?.status) {
      record.status = row.action.status;
    }

    return record;
  }

  const record = {
    id: String(row.id ?? row.record_id ?? row.pk ?? row.entry_id ?? row.lead_id ?? index),
    lead_id: row.lead_id ?? row.id,
    _mongoId: row.id,
    _rawLead: row,
  };

  columns.forEach((column) => {
    record[column.key] = row[column.key] ?? getLeadFieldValue(row, column.key) ?? '';
  });

  return record;
}

/**
 * Transforms GetB2B2CLeads API response into normalized rows.
 */
export function adaptB2b2cLeadsToRecords(raw, columns = []) {
  const payload = raw?.data && typeof raw.data === 'object' ? raw.data : raw;

  if (!payload || typeof payload === 'string') {
    return { rows: [], totalCount: 0, uniquePhoneCount: 0 };
  }

  const rawRows = payload.list ?? payload.records ?? payload.rows ?? [];
  const rows = Array.isArray(rawRows)
    ? rawRows.map((row, index) => normalizeRow(row, index, columns))
    : [];

  const totalCount = payload.count ?? payload.total_count ?? payload.totalCount ?? rows.length;
  const uniquePhoneCount =
    payload.unique_phone_count ?? payload.uniquePhoneCount ?? 0;

  return { rows, totalCount, uniquePhoneCount };
}

/**
 * Transforms GetLeadsEntries API response into normalized columns + rows.
 */
export function adaptLeadsEntriesToRecords(raw) {
  const payload = raw?.data && typeof raw.data === 'object' ? raw.data : raw;

  if (!payload || typeof payload === 'string') {
    return { columns: [], rows: [], totalCount: 0, uniquePhoneCount: 0 };
  }

  const rawColumns = payload.headers ?? payload.columns ?? payload.fields ?? [];
  const columns = Array.isArray(rawColumns)
    ? rawColumns.map(normalizeColumn).filter((col) => col?.key)
    : [];

  const rawRows = payload.values ?? payload.records ?? payload.rows ?? payload.results ?? [];
  const rows = Array.isArray(rawRows)
    ? rawRows.map((row, index) => normalizeRow(row, index, columns))
    : [];

  const totalCount =
    payload.total_count ??
    payload.totalCount ??
    payload.count ??
    rows.length;

  return {
    columns,
    rows,
    totalCount,
    uniquePhoneCount: payload.unique_phone_count ?? payload.uniquePhoneCount ?? 0,
  };
}

/**
 * Combines form schema + B2B2C lead records into table view model.
 */
export function adaptTableRecords(formPayload, recordsPayload) {
  const columns = adaptLeadsFormItemsToColumns(formPayload);

  if (columns.length === 0) {
    return adaptLeadsEntriesToRecords(recordsPayload);
  }

  const { rows, totalCount, uniquePhoneCount } = adaptB2b2cLeadsToRecords(recordsPayload, columns);
  return { columns, rows, totalCount, uniquePhoneCount };
}
